const missions=[{id:'test-game',title:'Bir oyunun ilk testçisi ol',desc:'Zıplama ve hareket kontrollerini dene. Tekrarlanabilir bir hata raporu üret.',type:'test',icon:'⌘',xp:70,duration:'10–15 dk',entry:'Yeni başlayan',benefit:'Geliştirici, sorunu tekrar üretebilen bir rapor alır.',output:'Beklenen sonuç, gerçekleşen sonuç, adımlar ve etki.',paid:'Gerçek projede ücret, kapsam ve kabul koşulları önceden belirlenir.'},{id:'test-cart',title:'Alışveriş akışını stres testine sok',desc:'Örnek sepetin miktar, toplam ve sıfırlama davranışlarını kontrol et.',type:'test',icon:'▤',xp:90,duration:'15 dk',entry:'Yeni başlayan',benefit:'Ürün ekibi, satış akışındaki tutarsızlığı tespit eder.',output:'Bir sepet hatası için net yeniden üretim adımları.',paid:'Bu demoda ödeme yapılmaz. Başlangıç görevi otomatik olarak ücretsiz iş değildir.'},{id:'copy',title:'Bir ekranı daha anlaşılır yap',desc:'Karışık bir başvuru metnini kullanıcının anlayacağı üç cümleye dönüştür.',type:'design',icon:'✎',xp:60,duration:'10 dk',entry:'Herkese açık',benefit:'Platform, kullanıcıyı yönlendiren daha iyi bir metin taslağı alır.',output:'Yeni metin ve neden daha anlaşılır olduğuna dair kısa açıklama.',paid:'Gerçek kullanım için içerik lisansı ve ödeme koşulları ayrıca onaylanır.'},{id:'big-project',title:'Erişilebilir mini oyun ekibine katıl',desc:'Seviyen ne olursa olsun, küçük bir denemeyle büyük bir projenin parçası ol.',type:'big',icon:'↗',xp:120,duration:'30 dk deneme',entry:'Seviye şartı yok',benefit:'Ekip, yetenekli yeni katılımcılara fırsat verir.',output:'Bir kontrol düzeni önerisi ve erişilebilirlik gerekçesi.',paid:'Seçim küçük denemenin niteliğine göre yapılır; mevcut seviye ön koşul değildir.'}];
const coursesBase=[{id:'testing',title:'Bir ürünü nasıl test ederim?',desc:'Geliştiricinin kullanabileceği bir hata raporu yaz. İlk katkını doğru yap.',teacher:'Deniz · örnek eğitmen',role:'Test & ürün',duration:'12 dk',xp:80,tag:'İlk adım',art:'game',color:'#e8def2',syllabus:['Hata ile kişisel tercihi ayır','Adımları tekrar üret','Etkiyi ve beklenen davranışı yaz'],lesson:'“Çalışmıyor” tek başına yeterli değildir. Ortamı, adımları, beklenen davranışı ve gerçekleşen davranışı ayır. Aynı adımlar aynı sorunu çıkarıyorsa rapor geliştirici için daha değerlidir. Ekran görüntüsü yardımcı olur; kişisel veri içermemesine dikkat et.',task:'Bir örnek üründe gördüğün veya bu platformun test görevinde bulduğun sorun için üç yeniden üretim adımı yaz. Beklenen ve gerçekleşen sonucu ayrıca belirt.'},{id:'prototype',title:'Fikri bir prototipe dönüştür',desc:'Mükemmel ürün yerine, test edilebilir tek bir işlev seç.',teacher:'Ece · örnek eğitmen',role:'Ürün tasarımı',duration:'18 dk',xp:100,tag:'Üretim pratiği',art:'desk',color:'#eee4d7',syllabus:['Kullanıcı ve ihtiyaç','En küçük işlev','Numune ve ilk deneme'],lesson:'Prototip bir fikri sınamak için yapılır. Kâğıt arayüz, karton maket ya da tek ekranlı oyun yeterli olabilir. Önce “hangi varsayımı test ediyorum?” sorusunu cevapla. Test için bir görev ver ve kullanıcıyı yönlendirmeden gözlemle.',task:'Bir kullanıcı ihtiyacı, tek bir ürün işlevi, prototip malzemesi ve başarı ölçütü yaz. Örn. kalemi 5 saniye içinde bulmak.'},{id:'teach',title:'Bildiğini öğretilebilir hale getir',desc:'Tek bir beceriden, sonuç üreten kısa bir topluluk eğitimi hazırla.',teacher:'Arda · örnek eğitmen',role:'Öğrenme tasarımı',duration:'15 dk',xp:90,tag:'Paylaşmaya başla',art:'design',color:'#dfe9d7',syllabus:['Tek bir öğrenme hedefi','Açık bir uygulama görevi','Geri bildirim ve örnek çıktı'],lesson:'Bir eğitim “ne anlattığın” kadar öğrencinin sonunda ne yapabildiğiyle de ilgilidir. Tek hedef seç, küçük bir örnek göster, uygulanabilir görev ver. Geri bildirim kişiye değil çıktıya odaklansın. Başlangıç seviyesindeki biri de iyi bildiği dar bir beceriyi öğretebilir.',task:'Öğreteceğin beceriyi, katılımcının sonunda oluşturacağı çıktıyı ve geri bildirimde bakacağın iki ölçütü yaz.'}];
const sampleProjects=[{id:'desk',title:'Modüler masa düzenleyici',type:'Fiziksel ürün',art:'desk',desc:'240 × 120 × 90 mm; 6 mm kontrplak. Kalem, telefon ve küçük eşyalar için üç bölme.',tasks:['Kullanıcı ihtiyacını ve masa ölçülerini belirle.','Ölçülü çizim ve karton maket hazırla.','Birleşim, stabilite ve kenarları numunede test et.','Üretici teklifi, finisaj, ambalaj ve teslim planı oluştur.']},{id:'planner',title:'Odak haftası planlayıcısı',type:'Dijital ürün',art:'design',desc:'İndirilebilir, tarihsiz A4 planlayıcı. Hedef, günlük işler ve üretim günlüğü tek sayfada.',tasks:['Hedef kullanıcıyı ve haftalık ihtiyacını yaz.','Bir planlayıcı düzeni oluştur.','A4 baskıda okunabilirliği ve yazılabilir alanı dene.','Teslim dosyası ve kullanım açıklamasını hazırla.']},{id:'coop',title:'İki kişi, bir devre',type:'Dijital oyun',art:'game',desc:'Parçaları birlikte planlayıp döndürerek akışı tamamlayan küçük bir tarayıcı oyunu.',tasks:['İş birliği kuralını ve kontrol biçimini tarif et.','Bir bölümün oynanabilir prototipini oluştur.','Yeni oyuncularla yönerge ve dokunmatik testi yap.','Lisansları, teslim paketini ve fiyat senaryosunu hazırla.']}];
const people=[{id:'deniz',name:'Deniz',initial:'D',role:'Test & ürün araştırması',skills:['Hata raporu','Kullanılabilirlik','Eğitim'],bio:'Üretim ekibiyle test yapanlar arasındaki dili anlaşılır kılmayı seviyor.',color:'#ead9ca'},{id:'ece',name:'Ece',initial:'E',role:'Ürün & fiziksel prototip',skills:['3B tasarım','Malzeme','Prototip'],bio:'Karton maketten ilk numuneye, küçük deneylerle ilerleyen bir üretici.',color:'#d8e5cc'},{id:'arda',name:'Arda',initial:'A',role:'Oyun & etkileşim',skills:['Oyun tasarımı','Kodlama','Erişilebilirlik'],bio:'Birlikte oynanan küçük dünyalar ve herkesin kullanabileceği kontroller tasarlıyor.',color:'#d9c9ee'},{id:'selin',name:'Selin',initial:'S',role:'Görsel iletişim',skills:['İllüstrasyon','Metin','Topluluk'],bio:'Bir fikri anlaşılır ve paylaşılabilir bir hikâyeye dönüştürüyor.',color:'#ecd4d3'}];
const pageNames={home:'Keşfet',missions:'Görev meydanı',academy:'İnsanlardan öğren',projects:'Üretim alanım',community:'Topluluk',funding:'Etki & destek',review:'Bağımsız inceleme'};let page='home',missionFilter='all',courseFilter='all',searchTerm='';
function xp(){return Object.values(state.awards).reduce((sum,x)=>sum+(Number(x)||0),0)}function level(){let i=0;levelMap.forEach((l,j)=>{if(xp()>=l.xp)i=j});return i}function save(){try{localStorage.setItem('scola-state',JSON.stringify(state))}catch{toast('Kalıcı kayıt kapalı; ilerleme yalnızca bu oturumda tutuluyor.')}updateIdentity()}
function addActivity(title,detail){state.activity.unshift({title,detail,time:new Date().toLocaleDateString('tr-TR')});state.activity=state.activity.slice(0,40)}function award(key,points){if(state.awards[key])return false;state.awards[key]=points;save();celebrate();return true}
function updateIdentity(){const name=live.user?.name||state.profile.name||'Sen',li=live.user?liveLevel():level();$('sideName').textContent=name+' · alanın';$('sideLevel').textContent='Seviye '+(li+1)+' · '+levelMap[li].name+(live.user?' ✓':'');document.querySelectorAll('.my-avatar').forEach(el=>el.textContent=name.slice(0,1).toLocaleUpperCase('tr'));$('notificationDot').style.display=state.activity.length?'block':'none'}
function intro(title,desc,button=''){return `<div class="page-intro"><div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`}function section(title,sub,action=''){return `<div class="section-head"><div><h2>${title}</h2><p>${sub}</p></div>${action}</div>`}function note(){return '<p class="demo-note">Eğitmenler, topluluk profilleri ve görevler örnektir. Paylaşımlar yalnızca bu tarayıcıda saklanır; gerçek eşleşme, ödeme veya fon transferi yapılmaz.</p>'}
function navigate(next){if(!pageNames[next])next='home';if(location.hash!=='#'+next)location.hash=next;else renderPage(next);$('sidebar').classList.remove('open')}
function renderPage(next){if(!pageNames[next])next='home';page=next;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('pageLabel').textContent=pageNames[page];$('main').className='page-enter';$('main').innerHTML=({home:renderHome,missions:renderMissions,academy:renderAcademy,projects:renderProjects,community:renderCommunity,funding:renderFunding,review:renderReview}[page])();if(page==='review'&&isReviewer())loadQueue();updateIdentity();window.scrollTo({top:0,behavior:'smooth'})}
function levelCard(){const verified=!!live.user,points=verified?live.xp:xp(),i=verified?liveLevel():level(),next=levelMap[i+1],pct=next?(points-levelMap[i].xp)/(next.xp-levelMap[i].xp)*100:100;return `<aside class="progress-card"><div class="eyebrow">SENİN YOLCULUĞUN</div><div class="level-row"><div class="level-icon">${i+1}</div><div><h3>${levelMap[i].name}</h3><p>Seviye ${i+1} · ${verified?'Doğrulanmış ilerleme':'Demo ilerlemesi'}</p></div></div><div class="progress-track"><span style="width:${pct}%"></span></div><div class="xp-label"><span>${points} XP</span><span>${next?next.xp+' XP →': 'Harita tamam'}</span></div><div class="impact-stats">${verified?`<div><strong>${live.accepted}</strong><small>Kabul edilen katkı</small></div>`:`<div><strong>${state.reports.length}</strong><small>Katkı taslağı</small></div>`}<div><strong>${Object.keys(state.completions).length}</strong><small>Eğitim çıktısı</small></div></div>${verified?`<p class="rounded-note">Bu tarayıcıdaki demo XP (${xp()}) doğrulanmış XP'ye çevrilmez.</p>`:live.available?'<button class="text-btn" onclick="openAccount(\'register\')">Gerçek katkı için hesap aç ↗</button><br>':''}<button class="text-btn" onclick="openLevels()">Bir sonraki adımın ne? ↗</button></aside>`}
function missionCard(m){const lm=live.user&&live.missions[m.id],done=lm?!!lm.myStatus:state.reports.some(r=>r.mission===m.id);return `<article class="mission-card"><div class="mission-top"><div class="mission-symbol">${m.icon}</div><span class="badge ${m.type==='big'?'orange':''}">${m.entry}</span></div><h3>${m.title}</h3><p>${m.desc}</p><div class="mission-meta"><span>◷ ${m.duration}</span><span>✦ +${m.xp} XP</span></div><div class="mission-foot"><strong>${lm&&lm.myStatus?statusText[lm.myStatus]:done?'✓ Katkı taslağı kaydedildi':m.type==='big'?'Yeteneğinle katıl':'Somut bir çıktı üret'}</strong><button class="text-btn" onclick="openMission('${m.id}')">${done?'İncele':'Görevi aç'} ↗</button></div></article>`}
function courseCard(c){const done=!!state.completions[c.id];return `<article class="course-card"><div class="course-cover" style="background:${c.color||'#e8def2'}"><span class="badge">${esc(c.tag||'Topluluk eğitimi')}</span>${artwork[c.art||'design']}</div><div class="course-body"><h3>${esc(c.title)}</h3><p>${esc(c.desc)}</p><div class="course-footer-meta"><span>◷ ${esc(c.duration||'Kendi hızında')}</span><span>✦ ${c.xp||60} XP</span></div><div class="teacher-row"><div class="avatar">${esc(c.teacher?.slice(0,1)||'S')}</div><span>${esc(c.teacher)}</span><button class="text-btn" onclick="openCourse('${c.id}')">${done?'✓ Çıktım':'Öğren'} ↗</button></div></div></article>`}
function renderHome(){const course=coursesBase.slice(0,3);return intro(`Selam ${esc(live.user?.name||state.profile.name)}. Bir adımın etkisi var. ✦`,'Merakını beceriye, becerini ortak bir işe dönüştür.',`<button class="btn light" onclick="openIdea()">＋ Bir fikrim var</button>`)+`<div class="hero-layout"><section class="hero"><div class="hero-copy"><div class="eyebrow">BİRLİKTE ÖĞREN. GERÇEK BİR ŞEYE KATKI VER.</div><h2>Burada izleyici değil,<br><em>üreticisin.</em></h2><p>Bir insandan öğren. Bir ürünü test et. Bildiğini paylaş. İlk gününden itibaren büyük bir işin küçük ama önemli parçası ol.</p><button class="btn lime" onclick="navigate('missions')">İlk katkını seç <span>↗</span></button></div><div class="hero-art">${artwork.hero}<span class="art-label">Öğrenme ↔ Üretim</span><span class="art-label bottom">✦ Küçük görev, gerçek katkı.</span></div></section>${levelCard()}</div><div class="path-strip"><div class="path-item"><span>◎</span><div><strong>Merakını seç</strong><small>Nereden başlamak istersin?</small></div></div><div class="path-item"><span>✳</span><div><strong>İnsanlardan öğren</strong><small>Uygulayarak, birlikte.</small></div></div><div class="path-item"><span>⚡</span><div><strong>Faydalı katkı ver</strong><small>Test, tasarım veya üretim.</small></div></div><div class="path-item"><span>↗</span><div><strong>Fikrini büyüt</strong><small>Ekip, kanıt ve destek.</small></div></div></div><div class="two-col"><div>${section('İlk katkın ne olsun?','Kısa görevler. Ürün ekibinin kullanabileceği çıktılar.',`<button class="text-btn" onclick="navigate('missions')">Tüm görevler ↗</button>`)}<div class="mission-grid">${missions.slice(0,2).map(missionCard).join('')}</div></div><aside class="right-rail"><div class="panel spotlight"><div class="eyebrow">SEVİYEN KAPINI KAPATMASIN</div><h3>Yeni başladın.<br>Büyük düşün.</h3><p>Büyük projeler için açık deneme yolu. Ünvan değil, ortaya koyduğun ilk örnek konuşsun.</p><button class="btn light small" onclick="openMission('big-project')">Açık denemeye gir ↗</button><span class="orbit-shape">✳</span></div><div class="panel activity-card"><h3><span class="pulse-signal"></span>Toplulukta neler olabilir?</h3><div class="activity-row"><div class="avatar" style="background:#e4d6f1">E</div><div><strong>Bir prototip, bir öğrenme anı.</strong><p>Ece’nin örnek dersinden ilk numuneye giden yolu incele.</p></div></div><div class="activity-row"><div class="avatar" style="background:#dbe7cf">D</div><div><strong>İyi bir rapor işi ilerletir.</strong><p>Deniz’in test eğitiminde hatayı yeniden üretmeyi öğren.</p></div></div></div></aside></div>${section('İnsanlardan öğren, bildiğini çoğalt.','Sadece video izleme. Dersin sonunda kendi çıktını oluştur.',`<button class="text-btn" onclick="navigate('academy')">Akademiye git ↗</button>`)}<div class="course-grid">${course.map(courseCard).join('')}</div><div class="manifesto"><span>↗</span><div><h3>Görünürlüğün, katkınla birlikte büyüsün.</h3><p>Seviye geçmişini gösterir. Destek değerlendirmesinde ürün kanıtı, ihtiyaç ve uygulama planı da yer alır.</p></div><button class="btn light small" onclick="navigate('funding')">Etki modelini gör ↗</button></div>${note()}`}
function renderMissions(){const list=missions.filter(m=>missionFilter==='all'||m.type===missionFilter);return intro('Görev meydanı.','İlk günden işe yarayan bir katkı. Büyük işler için de bir açık kapı.',`<button class="btn light" onclick="openReports()">Katkılarım (${state.reports.length}) ↗</button>`)+`<div class="notice"><strong>Başlangıç işi de değerli iştir.</strong> Gerçek görevlerde teslim kapsamı, süre, ücret, lisans ve kabul ölçütleri başlamadan görünür olur. Deneme görevleri sınırlandırılır; ücretsiz sınırsız üretim istenmez.</div><div class="tabs">${[['all','Tüm görevler'],['test','Ürün & oyun testi'],['design','Yaratıcı katkı'],['big','Büyük işlere açık deneme']].map(([id,title])=>`<button class="tab ${missionFilter===id?'active':''}" onclick="filterMissions('${id}')">${title}</button>`).join('')}</div><div class="mission-grid">${list.map(missionCard).join('')}</div><div class="first-timer"><span style="font-size:31px">✳</span><div><h3>Daha önce test yapmadın mı?</h3><p>12 dakikalık örnek eğitimden başla. Öğrendiğini ilk görevinde kullan.</p></div><button class="btn light small" onclick="openCourse('testing')">Test etmeyi öğren ↗</button></div>${note()}`}
function filterMissions(f){missionFilter=f;renderPage('missions')}
function allCourses(){return [...coursesBase,...state.courses]}
function renderAcademy(){const list=allCourses().filter(c=>courseFilter==='all'||(courseFilter==='mine'&&c.owned)||(courseFilter==='done'&&state.completions[c.id]));return intro('Bir insandan öğren. Bir insana öğret.','Kısa eğitim, somut uygulama, çıktıya dayalı geri bildirim.',`<button class="btn purple" onclick="openTeach()">＋ Eğitim oluştur</button>`)+`<div class="notice"><strong>Öğretmek için yüksek seviye şartı yok.</strong> İyi bildiğin dar bir beceriyi paylaşabilirsin. Önerilen canlı modelde eğitimler içerik, örnek çıktı ve katılımcı geri bildirimiyle değerlendirilir; yalnızca izlenme sayısıyla öne çıkarılmaz.</div><div class="tabs">${[['all','Tüm eğitimler'],['mine','Benim eğitimlerim'],['done','Tamamladıklarım']].map(([id,title])=>`<button class="tab ${courseFilter===id?'active':''}" onclick="filterCourses('${id}')">${title}</button>`).join('')}</div><div class="course-grid">${list.length?list.map(courseCard).join(''):'<div class="empty" style="grid-column:1/-1"><h3>Burada ilk çıktına yer var.</h3><p>Bir eğitim açabilir ya da mevcut bir derse başlayabilirsin.</p></div>'}</div>${section('Eğitim katkısı nasıl değer kazanır?','Canlı platform için önerilen kalite döngüsü.')}<div class="path-strip"><div class="path-item"><span>1</span><div><strong>Örnek çıktı</strong><small>Eğitmen neyi bildiğini gösterir.</small></div></div><div class="path-item"><span>2</span><div><strong>Uygulama</strong><small>Katılımcı bir ürün veya deneme yapar.</small></div></div><div class="path-item"><span>3</span><div><strong>Geri bildirim</strong><small>Çıktı ortak ölçütlerle değerlendirilir.</small></div></div><div class="path-item"><span>4</span><div><strong>Güven & görünürlük</strong><small>Doğrulanan katkı görünürlüğü artırır.</small></div></div></div>${note()}`}
function filterCourses(f){courseFilter=f;renderPage('academy')}
function renderProjects(){return intro('Senin üretim alanın.','Kendi ürününü kur. Öğrendiğini, katkını ve üretim planını bir araya getir.',`<button class="btn purple" onclick="openIdea()">＋ Proje başlat</button>`)+`${state.projects.length?'<div class="card-grid">'+state.projects.map((p,i)=>`<article class="project-card"><div class="project-title-row"><span class="badge purple">${esc(p.type)}</span><button class="remove-btn" onclick="confirmRemove(${i})" aria-label="Projeyi kaldır">×</button></div><h3>${esc(p.title)}</h3><p>${esc(p.desc||'İlk fikrinden üretim planına giden yol.')}</p><div class="project-progress"><span style="width:${(p.done||[]).filter(Boolean).length*25}%"></span></div><div class="progress-detail">${(p.done||[]).filter(Boolean).length}/4 adım · ${p.prototype?'Prototip beyanı var':'Fikir aşaması'}</div><button class="btn light small" onclick="openWorkspace(${i})">Çalışma alanı ↗</button></article>`).join('')+'</div>':'<div class="empty"><div class="empty-icon">◇</div><h3>İlk ürünün için bir masa hazır.</h3><p>Bir fikrin varsa başlat. Henüz yoksa aşağıdaki somut örneklerden birini seç.</p><button class="btn purple" onclick="openIdea()">Fikrimi ekle ↗</button><button class="btn light" onclick="openGame()">Örnek oyunu dene ▶</button></div>'}${section('Somut ürünler, somut üretim adımları.','Üretilebilir konseptler ve çalışan örnekler. Bunlar satışta olan ürünler değildir.')}<div class="card-grid">${sampleProjects.map(p=>`<article class="project-card"><div class="project-art">${artwork[p.art]}</div><span class="badge gray">${p.type}</span><h3>${p.title}</h3><p>${p.desc}</p><button class="btn light small" onclick="openProduct('${p.id}')">Ürünü incele ↗</button></article>`).join('')}</div>${note()}`}
function renderCommunity(){return intro('Tek başına başla. Birlikte ilerle.','Birbirini tamamlayan beceriler, öğretici ilişkiler ve ortak üretim.',`<button class="btn light" onclick="openProfile()">Profilimi düzenle ↗</button>`)+`<div class="notice">Bu bölümdeki kişiler örnek profillerdir. Canlı modelde öneriler; ortak ilgi, beceri uyumu, müsaitlik ve güven geçmişiyle yapılır. Yeni üreticiler için keşif kontenjanı ayrılır.</div><div class="community-grid">${people.map(p=>`<article class="person"><div class="avatar" style="background:${p.color}">${p.initial}</div><div><h3>${p.name} <span class="prototype-stage">ÖRNEK PROFİL</span></h3><div class="mentor-title">${p.role}</div><p>${p.bio}</p><div class="skill-tags">${p.skills.map(s=>'<span>'+s+'</span>').join('')}</div><button class="text-btn" onclick="openPerson('${p.id}')">Profil & birlikte üretim ↗</button></div></article>`).join('')}</div>${section('Bir grubun etrafında buluş.','Örnek çalışma çemberleri; katılım niyetini yerel olarak kaydedebilirsin.')}<div class="mission-grid"><div class="panel"><span class="badge purple">DİJİTAL ÜRETİM</span><h3>Oyun & ürün test çemberi</h3><p class="rounded-note">Yeni prototipleri dene, geliştiriciye net rapor ver. Kod bilmek ön koşul değil.</p><button class="btn light small" onclick="joinCircle('Oyun & ürün test çemberi')">Bu çemberi takip et ↗</button></div><div class="panel"><span class="badge orange">FİZİKSEL ÜRETİM</span><h3>Numune & tasarım çemberi</h3><p class="rounded-note">Çizim, karton maket, malzeme ve üretici iletişimini ortak bir masada buluştur.</p><button class="btn light small" onclick="joinCircle('Numune & tasarım çemberi')">Bu çemberi takip et ↗</button></div></div>${note()}`}
function fundScore(p){if(!p)return {total:0,parts:[0,0,0,0,0]};const f=p.readiness||{};const parts=[f.prototype?30:0,f.need?25:0,f.cost?20:0,f.team?15:0,f.contribution?10:0];return {total:parts.reduce((a,b)=>a+b,0),parts}}
function renderFunding(){const ready=state.projects.reduce((best,p)=>Math.max(best,fundScore(p).total),0);return intro('Etki kazan. Fikrini kanıtla. Destek bul.','Topluluk geçmişi değerli; yeni başlayan birinin güçlü prototipi de değerli.')+`<div class="fund-hero"><div><div class="eyebrow">KANITA DAYALI DESTEK MODELİ</div><h2>Seviyen bir sinyal.<br>Ürünün asıl hikâye.</h2><p>Fon hazırlığı; prototip, kullanıcı ihtiyacı, maliyet ve ekip planıyla oluşur. Topluluk katkısı destekleyici bir bileşendir. Yeni başlayanlar aynı ölçütlerle açık başvuru yapabilir.</p><button class="btn lime" onclick="openReadiness()">Hazırlık haritamı çıkar ↗</button></div><div class="fund-score"><div><strong>${ready}<span style="font-size:16px;letter-spacing:0"> / 100</span></strong><small>En yüksek proje hazırlık puanın</small><p style="font-size:9px;margin-bottom:0">Kendi beyanına dayalı demo. Fon onayı, kişi değeri veya şirket değerlemesi değildir.</p></div></div></div><div class="metrics"><div class="metric"><strong>${xp()}</strong><span>Demo deneyim puanı</span></div><div class="metric"><strong>${state.reports.length}</strong><span>Katkı taslağı</span></div><div class="metric"><strong>0</strong><span>Bağımsız doğrulanmış katkı</span></div><div class="metric"><strong>${state.applications.length}</strong><span>Destek başvuru taslağı</span></div></div><div class="fund-grid"><article class="fund-card"><span class="badge purple">YENİ ÜRETİCİLERE AÇIK</span><h3>İlk numune desteği</h3><p>Üretici teklifi ve prototip planıyla, ilk fiziksel numuneyi hayata geçirmek için taslak başvuru oluştur.</p><ul><li>Seviye ön koşulu yok.</li><li>Gider kalemleri ve teslim hedefi açık olmalı.</li><li>Gerçek bütçe, sponsor ve sözleşme gerektirir.</li></ul><button class="btn purple" onclick="openApplication('İlk numune desteği')">Başvuru taslağı oluştur ↗</button></article><article class="fund-card"><span class="badge orange">BÜYÜK İŞLERE AÇIK DENEME</span><h3>Proje ekibi & üretim desteği</h3><p>Dijital ürün veya oyun için bir ilk örnek, test sonucu ve ekip ihtiyacıyla destek yolunu planla.</p><ul><li>İlk turda isim ve seviye gizlenebilir.</li><li>Sonuçlar ortak kalite ölçütleriyle incelenir.</li><li>Gelir ve katkı paylaşımı işe başlamadan belirlenir.</li></ul><button class="btn light" onclick="openApplication('Proje ekibi & üretim desteği')">Destek planımı hazırla ↗</button></article></div>${section('Görünürlük nasıl adil kalır?','Seviye artarken yeni katılımcılar için kapı da açık kalmalı.')}<div class="panel"><table class="comparison"><thead><tr><th>ALAN</th><th>ÖNERİLEN SCOLA KURALI</th></tr></thead><tbody><tr><td>Keşif görünürlüğü</td><td>%40 katkı kalitesi + %25 konu uyumu + %20 yeni üretici keşfi + %15 güncellik. Öneri modeli; bu demoda sıralama uygulanmaz.</td></tr><tr><td>Seviye</td><td>Görev ve eğitim çıktısıyla gelişir. Takipçi sayısı veya harcanan para XP üretmez.</td></tr><tr><td>Eğitmen etkisi</td><td>Tamamlanan uygulamalar, faydalı geri bildirim ve bağımsız incelemeyle güçlenir.</td></tr><tr><td>Fon değerlendirmesi</td><td>Hazırlık puanında en fazla 10/100 topluluk katkısı; 90/100 ürün ve uygulama kanıtı.</td></tr><tr><td>İtiraz & güven</td><td>Çıkar çatışması, sahte değerlendirme ve karşılıklı XP şişirmesi için inceleme ve itiraz yolu.</td></tr></tbody></table></div>${note()}`}
function modal(html,wide=false){$('modalContent').innerHTML=html;$('modal').classList.toggle('wide',wide);if(!$('modal').open)$('modal').showModal()}
function closeModal(){$('modal').close()}function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').style.display='none',3500)}
function celebrate(){if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;$('confetti').innerHTML=Array.from({length:22},(_,i)=>`<i style="left:${Math.random()*100}%;background:${['#c5a5e9','#d7eca9','#efb28e'][i%3]};animation-delay:${Math.random()*.25}s"></i>`).join('');setTimeout(()=>$('confetti').innerHTML='',2100)}
function toggleMenu(){$('sidebar').classList.toggle('open')}function toggleHelper(){$('helperPanel').hidden=!$('helperPanel').hidden;$('helperButton').setAttribute('aria-expanded',String(!$('helperPanel').hidden))}function hideHelper(){$('helperPanel').hidden=true;$('helperButton').setAttribute('aria-expanded','false')}
function openLevels(){modal(`<div class="eyebrow">GELİŞİM HARİTASI</div><h2>Deneyim artar. Kapılar açık kalır.</h2><p>Demo XP kişisel ilerlemeyi gösterir. Canlı topluluk etkisi, bağımsız doğrulanmış katkılarla oluşmalıdır. Bu demoda bağımsız doğrulama yoktur.</p><div class="level-map">${levelMap.map((l,i)=>`<div class="${xp()>=l.xp?'unlocked':''}"><b class="number">${i+1}</b><div><strong>${l.name} · ${l.xp} XP</strong><small>${l.benefit}</small></div></div>`).join('')}</div><p>Hiçbir seviye eğitim açmanın, proje kurmanın veya büyük işlerin deneme başvurusunun ön koşulu değildir.</p>`)}
function openProfile(){modal(`<div class="eyebrow">TOPLULUK PROFİLİN</div><h2>Seni hangi merak anlatıyor?</h2><form id="profileForm"><label class="field" for="profileName">Görünen adın</label><input class="input" id="profileName" maxlength="40" required value="${esc(state.profile.name)}"><label class="field" for="profileInterest">İlgi alanın</label><input class="input" id="profileInterest" maxlength="100" value="${esc(state.profile.interest)}" placeholder="Oyun, tasarım, üretim…"><label class="field" for="profileBio">Birlikte ne yapmak istersin?</label><textarea id="profileBio" maxlength="600">${esc(state.profile.bio)}</textarea><div class="modal-actions"><button class="btn purple">Profilimi kaydet</button><button type="button" class="btn light" onclick="exportState()">Verilerimi indir ↓</button></div></form><p class="rounded-note">Bu profil gerçek bir kullanıcı hesabı değildir; sadece bu tarayıcıda tutulur.</p>`);$('profileForm').onsubmit=e=>{e.preventDefault();const name=$('profileName').value.trim();if(!name)return;state.profile={name,interest:$('profileInterest').value.trim(),bio:$('profileBio').value.trim()};save();closeModal();renderPage(page);toast('Profilin güncellendi.')};}
function openActivity(){modal(`<div class="eyebrow">SENİN AKIŞIN</div><h2>Her adımın bir izi var.</h2>${state.activity.length?state.activity.map(a=>`<div class="review-box"><strong>${esc(a.title)}</strong><br>${esc(a.detail)}<br><small>${esc(a.time)}</small></div>`).join(''):'<p>İlk görevini aç, bir eğitim tamamla ya da kendi projenle başla.</p>'}`)}
function exportState(){download('Scola_Ilerleme.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),state},null,2),'application/json')}
function download(name,data,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function openTeach(){modal(`<div class="eyebrow">BİLDİĞİNİ PAYLAŞ</div><h2>Bir ders değil, bir kazanım tasarla.</h2><p>Dar bir beceri seç. Katılımcı sonunda ne yapabilecek? Eğitimi burada oluşturabilir ve önizleyebilirsin.</p><form id="teachForm"><label class="field" for="teachTitle">Eğitim adı</label><input class="input" id="teachTitle" maxlength="100" required placeholder="Örn. İlk kullanılabilirlik raporun"><label class="field" for="teachDesc">Katılımcı ne kazanacak?</label><textarea id="teachDesc" minlength="30" maxlength="800" required></textarea><label class="field" for="teachSyllabus">Ders akışı <small>Her satıra bir bölüm</small></label><textarea id="teachSyllabus" maxlength="1500" required placeholder="Bir örnek göster\nBirlikte dene\nKendi çıktını üret"></textarea><label class="field" for="teachLesson">Anlatım / örnek içerik</label><textarea id="teachLesson" minlength="100" maxlength="6000" required></textarea><label class="field" for="teachTask">Uygulama görevi ve başarı ölçütü</label><textarea id="teachTask" minlength="40" maxlength="1500" required></textarea><p class="error" id="teachError"></p><button class="btn purple">Eğitim taslağını oluştur ↗</button></form><p class="rounded-note">Yerel taslak oluşturulur. Gerçek yayın için içerik incelemesi, telif kontrolü ve eğitmen koşulları gerekir. Kendi dersini tamamlamak XP üretmez.</p>`);$('teachForm').onsubmit=e=>{e.preventDefault();const values=['teachTitle','teachDesc','teachSyllabus','teachLesson','teachTask'].map(id=>$(id).value.trim());if(values.some(v=>!v))return;const [title,desc,syllabus,lesson,task]=values;state.courses.push({id:'own-'+uid(),title,desc,syllabus:syllabus.split('\n').filter(Boolean),lesson,task,owned:true,teacher:state.profile.name+' · senin taslağın',duration:'Kendi hızında',xp:60,tag:'Yerel eğitim taslağı',art:'design'});addActivity('Bir eğitim hazırladın',title);save();closeModal();courseFilter='mine';navigate('academy');toast('Eğitim taslağın hazır. Önizleyip kendi uygulama akışını dene.')};}
let currentCourseStep=0;
function openCourse(id,step=0){const c=allCourses().find(c=>c.id===id);if(!c)return;currentCourseStep=step;const done=state.completions[id];modal(`<div class="eyebrow">${esc(c.teacher)} · ${esc(c.duration||'Kendi hızında')}</div><h2>${esc(c.title)}</h2><div class="lesson-steps">${['Hedef & akış','Öğren & örnekle','Uygula & paylaş'].map((t,i)=>`<button class="lesson-step ${i===step?'active':''}" onclick="openCourse('${id}',${i})">${i+1}. ${t}</button>`).join('')}</div>${step===0?`<p>${esc(c.desc)}</p><div class="result"><strong>Ders akışı</strong><ol>${c.syllabus.map(s=>'<li>'+esc(s)+'</li>').join('')}</ol></div><button class="btn purple" onclick="openCourse('${id}',1)">Derse başla ↗</button>`:step===1?`<div class="read-note">${esc(c.lesson).replace(/\n/g,'<br>')}</div><div class="result"><strong>Bir an dur:</strong> Bu bilgiyi kendi ürününde nerede kullanabilirsin?</div><button class="btn purple" onclick="openCourse('${id}',2)">Uygulamaya geç ↗</button>`:`<p>${esc(c.task)}</p><label class="field" for="courseOutput">Uygulama çıktın</label><textarea id="courseOutput" maxlength="5000" placeholder="Somut örneğini, denemeni ve öğrendiğini yaz.">${esc(done?.output||state.notes['course-'+id]||'')}</textarea><label class="field">Bu eğitim sana ne kadar yardımcı oldu?</label><div class="rating">${[1,2,3,4,5].map(v=>`<button class="${v<= (done?.rating||0)?'selected':''}" onclick="setRating(${v})" aria-label="${v} yıldız">★</button>`).join('')}</div><input type="hidden" id="courseRating" value="${done?.rating||0}"><p class="error" id="courseError"></p><div class="modal-actions"><button class="btn light" onclick="courseDraft('${id}')">Taslağı sakla</button><button class="btn purple" onclick="completeCourse('${id}')">Çıktımı tamamladım ✓</button></div><p class="rounded-note">Kendi beyanına dayalı demo tamamlaması. ${c.owned?'Kendi eğitimin için XP verilmez.':'İlk tamamlamada +'+c.xp+' demo XP.'} Eğitmen puanı veya bağımsız doğrulama oluşturmaz.</p>`}`)}
function setRating(v){$('courseRating').value=v;document.querySelectorAll('.rating button').forEach((b,i)=>b.classList.toggle('selected',i<v))}function courseDraft(id){state.notes['course-'+id]=$('courseOutput').value.trim();save();toast('Uygulama taslağın kaydedildi.')}
function completeCourse(id){const output=$('courseOutput').value.trim();if(output.length<80){$('courseError').textContent='En az 80 karakterle somut bir uygulama çıktısı yaz.';return}const c=allCourses().find(c=>c.id===id);state.completions[id]={output,rating:Number($('courseRating').value),status:'Kendi beyanıyla tamamlandı'};if(!c.owned)award('course-'+id,c.xp);addActivity('Eğitim çıktısı oluşturuldu',c.title);save();closeModal();renderPage(page);toast('Çıktın kaydedildi. Öğrendiklerini bir görevde kullanabilirsin.')}
let currentMission='',testActions=0,testQty=1,testCount=0,testPosition=0;
function openMission(id){const m=missions.find(m=>m.id===id);currentMission=id;testActions=0;testQty=1;testCount=0;testPosition=0;const report=state.reports.find(r=>r.mission===id);modal(`<div class="eyebrow">GÖREV BRİFİNGİ · ${m.entry}</div><h2>${m.title}</h2><p>${m.desc}</p><div class="result"><strong>Bu katkı kimin işine yarar?</strong><br>${m.benefit}<br><strong>Teslim:</strong> ${m.output}<br><strong>Koşul:</strong> ${m.paid}</div>${contractBox(id)}${id==='test-game'?`<div class="test-box"><div class="test-screen"><small>KASITLI HATA İÇEREN TEST PROTOTİPİ</small><h3>Mini sıçrama</h3><div class="test-stage"><div class="test-character" id="testCharacter">◉</div></div><div class="test-controls"><button class="btn light small" onclick="testGame('left')">← Sol</button><button class="btn purple small" onclick="testGame('jump')">Zıpla ↑</button><button class="btn light small" onclick="testGame('right')">Sağ →</button><button class="btn light small" onclick="testGame('reset')">Sıfırla</button></div><div id="testStats" class="test-count">Hareket: 0 · Zıplama: 0</div></div></div>`:id==='test-cart'?`<div class="test-box"><div class="test-screen"><small>KASITLI HATA İÇEREN TEST PROTOTİPİ</small><h3>Örnek oyun paketi</h3><p>Birim fiyat: 100 ₺</p><div class="test-controls"><button class="btn light" onclick="testCart(-1)">−</button><strong id="cartQty" style="padding:10px">1</strong><button class="btn light" onclick="testCart(1)">＋</button><button class="btn light" onclick="resetCart()">Sepeti sıfırla</button></div><h3 id="cartTotal">Toplam: 100 ₺</h3></div></div>`:id==='copy'?'<div class="read-note">Özgün ekran metni: “Talebinizle ilgili sürecin prosedürel aşamalarına ilişkin değerlendirme neticesinde ilgili işlemler tarafınıza bildirilecek olup gerekli aksiyonları almanız beklenmektedir.”<br><br>Görev: Kullanıcının ne olacağını, ne zaman haber alacağını ve şu anda ne yapması gerektiğini anladığı bir taslak yaz. Bilinmeyen süreyi uydurma.</div>':'<div class="read-note">Deneme brifi: İki oyuncunun birlikte açtığı bir kapı için, tek elle de kullanılabilen kontrol düzeni öner. Tuşları, iş birliği kuralını ve ilk testte bakılacak iki ölçütü yaz. Önceden oyun geliştirmiş olman şart değil.</div>'}<p class="test-count" id="actionCount">${id.startsWith('test')?'Test etkileşimi: 0 · Teslimden önce en az 3 kontrol dene.':'Somut bir deneme veya yeni metin oluştur.'}</p><form id="reportForm"><label class="field" for="reportTitle">${id.startsWith('test')?'Sorunun kısa adı':'Çıktının kısa adı'}</label><input class="input" id="reportTitle" required maxlength="120" value="${esc(report?.title||'')}"><label class="field" for="reportOutput">${id.startsWith('test')?'Adımlar / beklenen sonuç / gerçekleşen sonuç':'Önerin ve gerekçen'}</label><textarea id="reportOutput" required minlength="100" maxlength="5000">${esc(report?.output||'')}</textarea><label class="field" for="reportImpact">Etki ve öncelik</label><select id="reportImpact"><option>Akışı engelliyor</option><option>Kullanımı zorlaştırıyor</option><option>İyileştirme önerisi</option></select><p class="error" id="reportError"></p><button class="btn purple">${live.user&&live.missions[id]?'Bağımsız incelemeye gönder ↗':'Katkı taslağını teslim et ↗'}</button></form><p class="rounded-note">${live.user&&live.missions[id]?'Teslimin yerel pilot sunucusuna kaydedilir ve kendi işi olmayan bir değerlendiriciye gider. XP yalnızca kabulde ve bir kez yazılır. Ödeme yapılmaz.':'Rapor gerçek bir geliştiriciye gönderilmez. İlk taslak teslimi demo XP verir; bağımsız kabul ve ücret oluşmaz.'}</p>`,true);$('reportForm').onsubmit=e=>{e.preventDefault();submitMission(id)}}
function updateTestActions(){testActions++;$('actionCount').textContent='Test etkileşimi: '+testActions+' · Kontrolleri karşılaştır ve raporunu yaz.'}
function testGame(action){updateTestActions();if(action==='left')testPosition=Math.max(-90,testPosition-15);if(action==='right')testPosition=Math.min(90,testPosition+15);if(action==='jump'){testCount++;$('testCharacter').style.transform=`translate(${testPosition}px,-40px)`;setTimeout(()=>{if($('testCharacter'))$('testCharacter').style.transform=`translate(${testPosition}px,0)`},250)}if(action==='reset'){testPosition=0;/* deliberately does not reset jump count: test exercise */}if(action!=='jump')$('testCharacter').style.transform=`translate(${testPosition}px,0)`;$('testStats').textContent='Hareket: '+testPosition+' · Zıplama: '+testCount}
function testCart(delta){testQty=Math.max(1,testQty+delta);updateTestActions();$('cartQty').textContent=testQty;$('cartTotal').textContent='Toplam: '+money(100*testQty)}function resetCart(){testQty=1;updateTestActions();$('cartQty').textContent='1';/* intentionally stale total, to teach reproducible reporting */}
function submitMission(id){const title=$('reportTitle').value.trim(),output=$('reportOutput').value.trim();if(title.length<4||output.length<100){$('reportError').textContent='Kısa bir ad ve en az 100 karakterlik somut bir çıktı ekle.';return}if(id.startsWith('test')&&testActions<3){$('reportError').textContent='Önce prototipte en az üç kontrol dene.';return}if(live.user&&live.missions[id])return submitLive(id,{title,output,impact:$('reportImpact').value});const report={mission:id,title,output,impact:$('reportImpact').value,status:'Yerel taslak · bağımsız inceleme bekler',date:new Date().toISOString()};const index=state.reports.findIndex(r=>r.mission===id);if(index<0)state.reports.push(report);else state.reports[index]=report;const m=missions.find(m=>m.id===id);award('mission-'+id,m.xp);addActivity('Faydalı bir katkı taslağı oluşturdun',title);save();closeModal();renderPage(page);toast('Katkın kaydedildi. Demo XP eklendi; gerçek inceleme yapılmadı.')}
function openReports(){modal(`<div class="eyebrow">KATKI PORTFOLYON</div><h2>İşin bir izi olsun.</h2>${live.user?'<h3>Doğrulanan ve incelemedeki teslimler</h3>'+liveReports()+'<h3>Bu tarayıcıdaki demo taslaklar</h3>':''}${state.reports.length?state.reports.map(r=>`<div class="review-box"><strong>${esc(r.title)}</strong><br>${esc(r.output).replace(/\n/g,'<br>')}<br><span class="badge gray">${esc(r.status)}</span></div>`).join(''):'<p>Bir test veya üretim görevi tamamlayarak ilk katkı taslağını oluştur.</p>'}<button class="btn light" onclick="exportState()">Portfolyo verilerimi indir ↓</button>`)}
function openIdea(){modal(`<div class="eyebrow">FİKİR → ÜRETİM</div><h2>İlk adımını tanımla.</h2><form id="ideaForm"><label class="field" for="ideaTitle">Projenin adı</label><input class="input" id="ideaTitle" required maxlength="100"><label class="field" for="ideaType">Ürün türü</label><select id="ideaType"><option>Dijital ürün</option><option>Fiziksel ürün</option><option>Dijital oyun</option><option>Topluluk projesi</option></select><label class="field" for="ideaDesc">Kimin hangi ihtiyacını çözüyor?</label><textarea id="ideaDesc" minlength="30" maxlength="1500" required></textarea><button class="btn purple" style="margin-top:20px">Çalışma alanını kur ↗</button></form>`);$('ideaForm').onsubmit=e=>{e.preventDefault();const title=$('ideaTitle').value.trim(),desc=$('ideaDesc').value.trim();if(!title||desc.length<30)return;state.projects.push({id:uid(),title,desc,type:$('ideaType').value,done:[false,false,false,false],tasks:['İhtiyacı ve hedef kullanıcıyı tarif et.','Tek işlevli bir prototip hazırla.','Bir kullanıcı denemesi yap ve gözlemleri kaydet.','Üretim, teslim ve maliyet planını çıkar.']});addActivity('Bir proje başlattın',title);save();closeModal();navigate('projects')};}
function openProduct(id){const p=sampleProjects.find(p=>p.id===id);modal(`<div class="eyebrow">${p.type} · ÜRÜN ÖRNEĞİ</div><h2>${p.title}</h2><div class="project-art">${artwork[p.art]}</div><p>${p.desc}</p><div class="result"><strong>Üretim yolu</strong><ol>${p.tasks.map(t=>'<li>'+t+'</li>').join('')}</ol></div><div class="modal-actions"><button class="btn purple" onclick="startProduct('${id}')">Bu projeden başla ↗</button>${id==='planner'?'<a class="btn light" href="assets/odak-haftasi.svg" download="Scola_Odak_Haftasi_A4.svg">Planlayıcıyı indir ↓</a>':id==='coop'?'<button class="btn light" onclick="openGame()">Oyunu dene ▶</button>':''}</div><p class="rounded-note">Fiziksel konsept ölçüleri üretim öncesi numunede doğrulanmalıdır. Fiyat veya hazır satış iddiası yoktur.</p>`)}
function startProduct(id){const sample=sampleProjects.find(p=>p.id===id);let i=state.projects.findIndex(p=>p.template===id);if(i<0){state.projects.push({...sample,id:uid(),template:id,done:[false,false,false,false]});i=state.projects.length-1;save()}openWorkspace(i)}
function openWorkspace(i){const p=state.projects[i];if(!p)return;modal(`<div class="eyebrow">ÜRETİM ALANIN · ${esc(p.type)}</div><h2>${esc(p.title)}</h2><p>${esc(p.desc)}</p>${p.tasks.map((t,j)=>`<label class="task"><input type="checkbox" ${(p.done||[])[j]?'checked':''} onchange="projectTask(${i},${j},this.checked)"><span>${esc(t)}</span></label>`).join('')}<label class="field" for="projectNote">Üretim günlüğü ve kanıt bağlantıları</label><textarea id="projectNote" maxlength="6000">${esc(p.note||'')}</textarea><div class="modal-actions"><button class="btn purple" onclick="saveProjectNote(${i})">Günlüğü kaydet</button><button class="btn light" onclick="saveProjectNote(${i});openBudget(${i})">Maliyet masası ↗</button><button class="btn light" onclick="saveProjectNote(${i});openReadiness(${i})">Destek hazırlığı ↗</button><button class="btn light" onclick="exportProject(${i})">Planı indir ↓</button></div><p class="rounded-note">Kendi beyanınla tamamlanan her adım bir kez +30 demo XP verir. Gerçek üretim doğrulaması veya fon onayı değildir.</p>`,true)}
function projectTask(i,j,checked){const p=state.projects[i];p.done=p.done||[false,false,false,false];p.done[j]=checked;if(checked)award('project-'+p.id+'-'+j,30);save();toast(checked?'Adım kaydedildi. Üretim izini günlüğüne ekle.':'Adım yeniden açıldı.');if(page==='projects')$('main').innerHTML=renderProjects()}
function saveProjectNote(i){state.projects[i].note=$('projectNote').value.trim();save();toast('Üretim günlüğün kaydedildi.')}
function confirmRemove(i){const p=state.projects[i];modal(`<h2>Bu projeyi kaldır?</h2><p>${esc(p.title)} ve yerel notları kaldırılır. İndirdiğin kopyalar etkilenmez.</p><div class="modal-actions"><button class="btn light" onclick="closeModal()">Vazgeç</button><button class="btn purple" onclick="removeProject(${i})">Projeyi kaldır</button></div>`)}function removeProject(i){state.projects.splice(i,1);save();closeModal();renderPage('projects')}
function exportProject(i){const p=state.projects[i];download('Scola_Proje_Plani.txt',p.title+'\n'+p.type+'\n\n'+p.desc+'\n\n'+p.tasks.map((t,j)=>((p.done||[])[j]?'[x] ':'[ ] ')+t).join('\n')+'\n\nÜRETİM GÜNLÜĞÜ\n'+(p.note||'')+'\n\nMALİYET SENARYOSU\n'+JSON.stringify(p.budget||{},null,2))}
function openBudget(i){const b=state.projects[i].budget||{price:200,cost:80,quantity:20,fixed:1000,fee:10};modal(`<div class="eyebrow">VARSAYIMSAL MALİYET MASASI</div><h2>Fikrin hesabını da yap.</h2><p>Varsayımsal rakamları gerçek tekliflerinle değiştir. İşçilik ve vergileri maliyetlere sen dahil etmelisin; sonuç bir yatırım önerisi değildir.</p><div class="budget-row">${[['price','Birim satış fiyatı (₺)'],['cost','Birim değişken maliyet (₺)'],['quantity','Satış adedi'],['fixed','Başlangıç gideri (₺)'],['fee','Kanal kesintisi (%)']].map(([k,t])=>`<label class="field">${t}<input class="input" type="number" id="budget-${k}" min="0" ${k==='fee'?'max="100"':''} step="${k==='quantity'?'1':'.01'}" value="${b[k]}" oninput="calcBudget(${i})"></label>`).join('')}</div><div id="budgetResult" class="result" aria-live="polite"></div><button class="btn light" onclick="openWorkspace(${i})">← Çalışma alanı</button>`);calcBudget(i)}
function calcBudget(i){const b={};for(const k of ['price','cost','quantity','fixed','fee']){b[k]=Number($('budget-'+k).value);if(!Number.isFinite(b[k])||b[k]<0||(k==='fee'&&b[k]>100)||(k==='quantity'&&!Number.isInteger(b[k]))){$('budgetResult').textContent='Sıfır veya pozitif değerler gir; adet tam sayı, kesinti %0–100 olmalı.';return}}const unit=b.price*(1-b.fee/100)-b.cost;const profit=unit*b.quantity-b.fixed;state.projects[i].budget=b;save();$('budgetResult').innerHTML=`<div class="finance-preview"><div><strong>${money(b.price*b.quantity)}</strong><small>Brüt satış</small></div><div><strong>${money(profit)}</strong><small>Tahmini faaliyet sonucu</small></div><div><strong>${unit>0?Math.ceil(b.fixed/unit)+' adet':'Yok'}</strong><small>Başabaş</small></div></div><small>Sonuç = satış − değişken gider − kanal kesintisi − başlangıç gideri. Birim katkı: ${money(unit)}.</small>`}
function openReadiness(i){if(!state.projects.length){modal('<h2>Önce bir projeye yer aç.</h2><p>Hazırlık puanı bir kişiyi değil, bir projenin hazırlığını değerlendirmek için kullanılır.</p><button class="btn purple" onclick="openIdea()">Proje başlat ↗</button>');return}if(i===undefined)i=0;const p=state.projects[i],f=p.readiness||{};modal(`<div class="eyebrow">FON HAZIRLIĞI · KENDİ BEYANIN</div><h2>${esc(p.title)}</h2><label class="field" for="readinessProject">Proje seç</label><select id="readinessProject" onchange="openReadiness(Number(this.value))">${state.projects.map((pr,j)=>`<option value="${j}" ${i===j?'selected':''}>${esc(pr.title)}</option>`).join('')}</select><div class="fund-check">${[['prototype','Çalışan veya gösterilebilir prototipim var.',30],['need','Hedef kullanıcının ihtiyacını bir test veya görüşmeyle sınadım.',25],['cost','Maliyet ve üretim / teslim planım var.',20],['team','Ekip rolleri ve iş planı belirli.',15],['contribution','Topluluk katkılarıma ilişkin kanıtım var.',10]].map(([k,label,points])=>`<label><input type="checkbox" id="ready-${k}" ${f[k]?'checked':''} onchange="calcReady(${i})"><span>${label} <small>(+${points})</small></span></label>`).join('')}</div><label class="field" for="readinessEvidence">Kanıtları ve eksikleri yaz</label><textarea id="readinessEvidence" maxlength="3000" placeholder="Prototip, kullanıcı denemesi, teklif, rol planı…">${esc(p.evidence||'')}</textarea><div class="result" id="readinessScore"></div><div class="modal-actions"><button class="btn purple" onclick="saveReadiness(${i})">Hazırlık taslağını sakla</button><button class="btn light" onclick="openApplication('Açık proje desteği',${i})">Başvuru planı ↗</button></div><p class="rounded-note">Kendi işaretlediğin ölçütlerdir; bağımsız inceleme değildir. 70 puan bir öneri eşiğidir, otomatik fon hakkı doğurmaz. Yeni katılımcı da topluluk katkısı olmadan 90 puana ulaşabilir.</p>`);calcReady(i)}
function calcReady(i){const flags={};for(const k of ['prototype','need','cost','team','contribution'])flags[k]=$('ready-'+k).checked;state.projects[i].readiness=flags;const score=fundScore(state.projects[i]);$('readinessScore').innerHTML=`<strong class="score-value">${score.total}/100</strong><br>${score.total>=70?'Önerilen başvuru eşiğine ulaştın. Kanıtlarını bağımsız incelemeye sunmak gerekir.':'İlk adım: prototip, kullanıcı denemesi ve maliyet planındaki eksikleri tamamla.'}`;save()}
function saveReadiness(i){state.projects[i].evidence=$('readinessEvidence').value.trim();save();toast('Hazırlık haritan kaydedildi.');closeModal();navigate('funding')}
function openApplication(program,i=0){if(!state.projects.length){openReadiness();return}modal(`<div class="eyebrow">DESTEK BAŞVURUSU · YEREL TASLAK</div><h2>${esc(program)}</h2><p>Talep edilen destek ürüne ve giderlere bağlıdır. Bu tutar kişi veya şirket değerlemesi değildir.</p><form id="applicationForm"><label class="field" for="applyProject">Projen</label><select id="applyProject">${state.projects.map((p,j)=>`<option value="${j}" ${j===i?'selected':''}>${esc(p.title)}</option>`).join('')}</select><label class="field" for="applyAmount">Talep edilen bütçe (₺)</label><input class="input" type="number" min="1" step="1" required id="applyAmount" placeholder="Gerçek gider planına göre"><label class="field" for="applyUse">Gider kalemleri, hedef çıktı ve teslim planı</label><textarea id="applyUse" required minlength="80" maxlength="4000"></textarea><label class="field" for="applyShare">Ekip katkısı ve önerilen paylaşım</label><textarea id="applyShare" maxlength="2000" placeholder="Roller, emek, haklar ve gelir paylaşımı hakkında taslak"></textarea><button class="btn purple" style="margin-top:18px">Başvuru taslağını kaydet ↗</button></form><p class="rounded-note">Sponsor, gerçek fon havuzu veya ödeme altyapısı bağlı değildir. Başvuru kimseye gönderilmez; gerçek destek bağımsız inceleme ve sözleşme gerektirir.</p>`);$('applicationForm').onsubmit=e=>{e.preventDefault();const amount=Number($('applyAmount').value),use=$('applyUse').value.trim();if(!Number.isFinite(amount)||amount<=0||use.length<80)return;const p=state.projects[Number($('applyProject').value)];state.applications.push({id:uid(),project:p.id,program,amount,use,share:$('applyShare').value.trim(),status:'Yerel taslak'});addActivity('Destek planı hazırlandı',p.title+' · '+money(amount)+' bütçe talebi');save();closeModal();navigate('funding');toast('Başvuru taslağın saklandı; herhangi bir kuruma gönderilmedi.')};}
function openPerson(id){const p=people.find(x=>x.id===id);modal(`<div class="eyebrow">ÖRNEK TOPLULUK PROFİLİ</div><h2>${p.name} · ${p.role}</h2><p>${p.bio}</p><div class="badge-list">${p.skills.map(s=>'<span>'+s+'</span>').join('')}</div><div class="result">Birlikte üretim önerisi: kısa bir ilk görüşme, tek bir ortak çıktı, açık görev paylaşımı. Gerçek platformda müsaitlik ve karşılıklı onay gerekir.</div><button class="btn purple" onclick="saveInterest('${id}')">Birlikte üretme niyetimi sakla ↗</button><p class="rounded-note">Bu örnek profile mesaj gönderilmez.</p>`)}
function saveInterest(id){if(!state.favorites.includes(id)){state.favorites.push(id);addActivity('Birlikte üretim niyeti',people.find(p=>p.id===id).name+' örnek profili');save()}closeModal();toast('Birlikte üretim niyetin yerel olarak saklandı.')}
function joinCircle(name){if(!state.favorites.includes(name)){state.favorites.push(name);addActivity('Bir çalışma çemberini takip ettin',name);save()}toast('Çember ilgilerin arasına eklendi. Gerçek bir gruba katılım yapılmadı.')}
function openChallenge(){const options=['Masandaki bir sorunu çözen üç bölmeli ürün çiz.','İki kişinin birlikte açacağı bir kapı için oyun kuralı yaz.','Bir ekranın karışık metnini tek bir eyleme dönüştür.'];const task=options[Math.floor(Math.random()*options.length)];modal(`<div class="eyebrow">10 DAKİKALIK MERAK DENEYİ</div><h2>Bir küçük şey dene.</h2><div class="result">${task}</div><label class="field" for="challengeOutput">Denemenin izi</label><textarea id="challengeOutput" maxlength="2000">${esc(state.notes.challenge||'')}</textarea><button class="btn purple" style="margin-top:18px" onclick="saveChallenge()">Denememi sakla ↗</button>`)}function saveChallenge(){const text=$('challengeOutput').value.trim();if(text.length<30){toast('Denemeni en az 30 karakterle anlat.');return}state.notes.challenge=text;award('challenge-first',30);addActivity('Küçük bir deneme yaptın',text.slice(0,80));save();closeModal();renderPage(page);toast('Denemen kaydedildi. İlk deneme ödülü bir kez verilir.')}
let board=[],gameMoves=0,gameWon=false;const pipeSymbols={'0,2':'│','1,3':'─','0,1':'└','1,2':'┌','2,3':'┐','0,3':'┘'};
function openGame(){board=[[0,2],[0,2],[0,1],[0,1],[0,2],[0,1],[0,2],[0,2],[0,1],[0,2],[0,2],[0,1],[0,2],[0,1],[0,1],[0,2]];gameMoves=0;gameWon=false;modal(`<div class="eyebrow">ÖRNEK ÜRÜN · İKİ KİŞİ, BİR DEVRE</div><h2>Akışı birlikte kurun.</h2><p>Parçaya dokunarak 90° döndür. Sol üst girişten sağ alt çıkışa yol kur. Bir arkadaşın rotayı planlasın, sen parçaları çevir; sonra rolleri değişin.</p><div id="gameBoard" class="game-grid"></div><p id="gameMessage" role="status">Giriş soldan, çıkış sağa. Komşu parçalar birbirine bakmalı.</p><div class="modal-actions"><button class="btn purple" onclick="checkGame()">Akışı dene ⚡</button><button class="btn light" onclick="openGame()">Yeniden başla</button></div><p class="rounded-note">Tek cihazda sırayla iş birliği demosu. İlk çözüm +100 demo XP.</p>`);renderBoard()}
function renderBoard(lit=[]){$('gameBoard').innerHTML=board.map((p,i)=>`<button class="tile ${i===0?'source':i===15?'target':''} ${lit.includes(i)?'lit':''}" onclick="rotateTile(${i})" aria-label="${Math.floor(i/4)+1}. satır ${i%4+1}. sütun döndür">${pipeSymbols[[...p].sort().join(',')]}${i===0?'<small>GİRİŞ →</small>':i===15?'<small>ÇIKIŞ →</small>':''}</button>`).join('')}
function rotateTile(i){if(gameWon)return;board[i]=board[i].map(x=>(x+1)%4);gameMoves++;renderBoard();$('gameMessage').textContent=gameMoves+' hamle. Akış hazırsa dene.'}
function traceBoard(){let idx=0,incoming=3;const seen=new Set(),path=[];while(true){if(seen.has(idx)||!board[idx].includes(incoming))return {won:false,path};seen.add(idx);path.push(idx);const out=board[idx].find(x=>x!==incoming);if(idx===15&&out===1)return {won:true,path};const r=Math.floor(idx/4)+[-1,0,1,0][out],c=idx%4+[0,1,0,-1][out];if(r<0||r>3||c<0||c>3)return {won:false,path};idx=r*4+c;incoming=(out+2)%4}}
function checkGame(){const result=traceBoard();renderBoard(result.path);if(result.won){gameWon=true;const fresh=award('game-circuit',100);$('gameMessage').textContent='Devre tamam! '+gameMoves+' hamle. '+(fresh?'+100 demo XP.':'XP ödülü daha önce kazanıldı.');save();}else $('gameMessage').textContent='Akış '+result.path.length+' parça ilerledi. Son parçanın çıkışını ve bir sonraki bağlantıyı kontrol et.'}
function openModel(){modal(`<div class="eyebrow">SCOLA · ÜRÜN MODELİ</div><h2>Öğrenme → katkı → üretim → etki.</h2><div class="result"><strong>1. İnsanlardan öğren.</strong> Kısa eğitim + uygulama çıktısı + geri bildirim.<br><strong>2. Faydalı iş yap.</strong> Test raporu, tasarım, içerik veya prototip.<br><strong>3. Güven inşa et.</strong> Canlı modelde bağımsız değerlendirme ve katkı kanıtı.<br><strong>4. Daha görünür ol.</strong> Konu uyumu, kalite ve yeni üretici keşfi dengelenir.<br><strong>5. Destek ara.</strong> Ürünün kanıtı, ihtiyacı, maliyeti ve ekibi incelenir.</div><p>Seviye insanın parasal değeri değildir. Proje veya şirket değerlemesi; doğrulanmış ürün, talep, gelir, haklar ve riskler hakkında ayrı bir inceleme gerektirir.</p><p>Yerel pilot sunucusuyla hesap, görev teslimi, kör bağımsız inceleme, itiraz ve sunucuda tutulan tekil XP çalışır. Eğitim yayın onayı, ekip eşleşmesi, ödeme ve fon transferi sonraki geliştirme aşamasıdır.</p>`,true)}
function searchPlatform(){const q=searchTerm.toLocaleLowerCase('tr-TR');if(q.length<2)return;const hits=[...missions.map(m=>({title:m.title,desc:m.desc,type:'Görev',action:`openMission('${m.id}')`})),...allCourses().map(c=>({title:c.title,desc:c.desc,type:'Eğitim',action:`openCourse('${c.id}')`})),...sampleProjects.map(p=>({title:p.title,desc:p.desc,type:'Ürün',action:`openProduct('${p.id}')`}))].filter(x=>(x.title+' '+x.desc).toLocaleLowerCase('tr-TR').includes(q));modal(`<div class="eyebrow">ARAMA</div><h2>“${esc(searchTerm)}”</h2><div class="search-results">${hits.length?hits.map(h=>`<button class="search-hit" onclick="${h.action}"><span class="badge gray">${h.type}</span><strong>${esc(h.title)}</strong><small>${esc(h.desc)}</small></button>`).join(''):'<p>Bir sonuç bulunamadı. Test, oyun veya prototip gibi bir kelime dene.</p>'}</div>`)}
// ---- Canlı pilot: sunucu hesabı, gerçek teslim, bağımsız inceleme, doğrulanmış XP ----
// Sunucu yoksa (dosya olarak açıldığında veya statik barındırmada) yalnızca demo çalışır.
let live={available:false,user:null,xp:0,accepted:0,pending:0,missions:{},submissions:[],queue:[],users:[]};
const isReviewer=()=>!!live.user?.roles.includes('reviewer'),isAdmin=()=>!!live.user?.roles.includes('admin');
const statusText={submitted:'Bağımsız incelemede',revision:'Revizyon istendi',accepted:'Kabul edildi',rejected:'Kabul edilmedi',appealed:'İtiraz · başka değerlendiricide'};
const statusBadge=s=>`<span class="badge ${s==='accepted'?'':s==='rejected'?'orange':s==='revision'?'purple':'gray'}">${statusText[s]||esc(s)}</span>`;
async function api(method,url,body){if(typeof fetch!=='function')throw new Error('Sunucu bağlantısı yok.');const res=await fetch(url,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data={};try{data=await res.json()}catch{}if(!res.ok)throw Object.assign(new Error(data.message||'İstek tamamlanamadı.'),{code:data.error,status:res.status});return data}
async function refreshLive(){try{const me=await api('GET','/api/me');live.user=me.user;live.xp=me.xp||0;live.accepted=me.accepted||0;live.pending=me.pending||0;const ms=await api('GET','/api/missions');live.missions=Object.fromEntries(ms.missions.map(m=>[m.id,m]));live.submissions=live.user?(await api('GET','/api/me/submissions')).submissions:[]}catch{}updateLiveChrome()}
async function initLive(){if(typeof fetch!=='function'||location.protocol==='file:')return;try{const h=await api('GET','/api/health');live.available=!!h.ok}catch{return}await refreshLive();renderPage(page)}
function liveLevel(){let i=0;levelMap.forEach((l,j)=>{if(live.xp>=l.xp)i=j});return i}
function updateLiveChrome(){const nav=$('reviewNav');if(nav)nav.hidden=!isReviewer();const acc=$('accountButton');if(acc){acc.hidden=!live.available;acc.textContent=live.user?'Hesabım':'Giriş yap'}}
function openAccount(mode='login'){if(!live.available)return toast('Gerçek hesap için yerel sunucuyu başlat: npm run dev');if(live.user){const i=liveLevel();return modal(`<div class="eyebrow">SCOLA HESABIN · YEREL PİLOT</div><h2>${esc(live.user.name)}</h2><p>${esc(live.user.email)}</p><div class="result"><strong>Doğrulanmış XP:</strong> ${live.xp} · Seviye ${i+1} · ${levelMap[i].name}<br><strong>Kabul edilen katkı:</strong> ${live.accepted} · <strong>İncelemede:</strong> ${live.pending}<br><strong>Roller:</strong> ${live.user.roles.map(r=>({producer:'Üretici',reviewer:'Değerlendirici',admin:'Yönetici'}[r]||esc(r))).join(', ')}</div><p class="rounded-note">Doğrulanmış XP yalnızca başka bir değerlendiricinin kabul ettiği teslimlerden doğar. Bu tarayıcıdaki demo XP (${xp()}) buraya aktarılmaz.</p><div class="modal-actions"><button class="btn purple" onclick="openReports()">Portfolyom ↗</button>${isReviewer()?'<button class="btn light" onclick="closeModal();navigate(\'review\')">İnceleme kuyruğu ↗</button>':''}<button class="btn light" onclick="logout()">Çıkış yap</button></div>`)}
const reg=mode==='register';modal(`<div class="eyebrow">SCOLA HESABI · YEREL PİLOT</div><h2>${reg?'Hesap oluştur.':'Tekrar hoş geldin.'}</h2><p>${reg?'Gerçek teslimlerin bağımsız değerlendiriciye gider; kabul edilen katkı portfolyona ve doğrulanmış XP\'ne yazılır.':'Teslimlerini, inceleme sonuçlarını ve doğrulanmış XP\'ni gör.'}</p><form id="authForm">${reg?'<label class="field" for="authName">Görünen adın</label><input class="input" id="authName" required minlength="2" maxlength="40" autocomplete="nickname">':''}<label class="field" for="authEmail">E-posta</label><input class="input" id="authEmail" type="email" required maxlength="120" autocomplete="email"><label class="field" for="authPassword">Şifre</label><input class="input" id="authPassword" type="password" required minlength="8" autocomplete="${reg?'new-password':'current-password'}">${reg?'<label class="field" for="authInterest">İlgi alanın (isteğe bağlı)</label><input class="input" id="authInterest" maxlength="100" placeholder="Oyun, tasarım, el sanatı, ticaret…">':''}<p class="error" id="authError" role="alert"></p><div class="modal-actions"><button class="btn purple">${reg?'Hesabımı oluştur':'Giriş yap'}</button><button type="button" class="btn light" onclick="openAccount('${reg?'login':'register'}')">${reg?'Hesabım var':'Yeni hesap aç'}</button></div></form><p class="rounded-note">Bu yerel pilot sunucusudur: veriler bu bilgisayardaki data/ klasöründe tutulur. Ödeme, e-posta doğrulama ve veli onayı henüz yoktur.</p>`);$('authForm').onsubmit=async e=>{e.preventDefault();try{await api('POST',reg?'/api/auth/register':'/api/auth/login',reg?{name:$('authName').value,email:$('authEmail').value,password:$('authPassword').value,interest:$('authInterest').value}:{email:$('authEmail').value,password:$('authPassword').value});await refreshLive();closeModal();renderPage(page);toast(reg?'Hesabın oluşturuldu.':'Giriş yapıldı.')}catch(err){$('authError').textContent=err.message}}}
async function logout(){try{await api('POST','/api/auth/logout',{})}catch{}live.user=null;live.xp=0;live.submissions=[];await refreshLive();closeModal();navigate('home');toast('Çıkış yapıldı.')}
function contractBox(id){const m=live.missions[id];if(!m)return '';const left=Math.max(0,m.maxAttempts-m.attemptsUsed);return `<div class="review-box"><strong>GÖREV SÖZLEŞMESİ · sunucuda tanımlı</strong><br><strong>Kapsam:</strong> ${esc(m.scope)}<br><strong>Süre:</strong> ${esc(m.duration)} · <strong>Doğrulanmış XP:</strong> +${m.xp} (yalnızca kabulde, bir kez)<br><strong>Kabul ölçütleri:</strong><br>${m.acceptance.map(a=>'· '+esc(a)).join('<br>')}<br><strong>Ücret:</strong> ${esc(m.payment.label)} — ${esc(m.payment.detail)}<br><strong>Lisans:</strong> ${esc(m.license)}<br><strong>Katkı payı:</strong> ${esc(m.share)}<br>${live.user?`<strong>Deneme hakkın:</strong> ${left} / ${m.maxAttempts}${m.myStatus?' · Son durum: '+statusBadge(m.myStatus):''}`:`<button type="button" class="text-btn" onclick="openAccount()">Gerçek teslim için giriş yap ↗</button>`}</div>`}
async function submitLive(id,payload){try{const r=await api('POST',`/api/missions/${encodeURIComponent(id)}/submissions`,payload);addActivity('Gerçek bir teslim bağımsız incelemeye gitti',payload.title);save();await refreshLive();closeModal();renderPage(page);toast(r.submission.attempt&&r.submission.status==='submitted'?'Teslimin incelemeye gönderildi. XP yalnızca bağımsız kabulden sonra yazılır.':'Teslim kaydedildi.')}catch(err){$('reportError').textContent=err.message}}
function liveReports(){if(!live.submissions.length)return '<p>Henüz gerçek teslimin yok. Görev meydanından bir görev aç ve teslim et.</p>';return live.submissions.map(s=>`<div class="review-box"><strong>${esc(s.title)}</strong> ${statusBadge(s.status)}<br><small>${esc(s.missionTitle)} · deneme ${s.attempt}${s.xpAwarded?' · +'+s.xpAwarded+' doğrulanmış XP':''}</small><br>${esc(s.output).replace(/\n/g,'<br>')}${s.reviews.map(r=>`<div class="rounded-note"><strong>${esc(r.reviewer)} · ${{accept:'Kabul',revise:'Revizyon',reject:'Ret'}[r.decision]}:</strong> ${esc(r.feedback)}</div>`).join('')}${s.status==='revision'?`<button class="text-btn" onclick="openMission('${esc(s.missionId)}')">Revize edip yeniden teslim et ↗</button>`:''}${s.status==='rejected'&&!s.appeal?`<button class="text-btn" onclick="openAppeal('${esc(s.id)}')">İtiraz et ↗</button>`:''}</div>`).join('')}
function openAppeal(id){modal(`<div class="eyebrow">İTİRAZ</div><h2>Başka bir değerlendirici baksın.</h2><p>İtirazın, ilk kararı vermeyen bir değerlendiriciye gider. Her teslim için bir itiraz hakkın var.</p><form id="appealForm"><label class="field" for="appealReason">Neden yeniden incelenmeli?</label><textarea id="appealReason" required minlength="20" maxlength="1000"></textarea><p class="error" id="appealError" role="alert"></p><button class="btn purple">İtirazı gönder</button></form>`);$('appealForm').onsubmit=async e=>{e.preventDefault();try{await api('POST',`/api/submissions/${encodeURIComponent(id)}/appeal`,{reason:$('appealReason').value});await refreshLive();openReports();toast('İtirazın kaydedildi.')}catch(err){$('appealError').textContent=err.message}}}
function renderReview(){if(!live.available)return intro('Bağımsız inceleme.','Bu bölüm yerel pilot sunucusuyla çalışır.')+`<div class="notice">Sunucu bağlantısı yok. <code>npm run dev</code> ile başlatıp http://127.0.0.1:5175 adresinden aç.</div><div class="result"><strong>1. Teslim.</strong> Görev sözleşmesindeki kapsam ve kabul ölçütlerine göre çıktını gönderirsin.<br><strong>2. Kör inceleme.</strong> Adın ve seviyen gizli; kendi işin olmayan yetkili bir değerlendirici ölçütleri tek tek işaretler.<br><strong>3. Karar.</strong> Kabul, revizyon veya ret; her kararda faydalı geri bildirim zorunlu.<br><strong>4. Doğrulanmış XP.</strong> Yalnızca kabulde, kullanıcı + görev başına bir kez sunucuda yazılır.<br><strong>5. İtiraz.</strong> Ret kararına bir kez itiraz edebilirsin; ilk kararı vermeyen biri bakar.</div>`;if(!isReviewer())return intro('Bağımsız inceleme.','Teslimleri, kendi işi olmayan yetkili değerlendiriciler inceler.')+`<div class="notice">Bu kuyruğu yalnızca yönetici tarafından yetkilendirilen değerlendiriciler görür. ${live.user?'Hesabında değerlendirici rolü yok.':'<button class="text-btn" onclick="openAccount()">Giriş yap ↗</button>'}</div>`;
const q=live.queue;return intro('Bağımsız inceleme.','Kör inceleme: katılımcının adı ve seviyesi gizli. Kendi teslimin, önceden incelediğin ya da çıkar çatışması beyan ettiğin teslimler kuyruğa gelmez.',`<button class="btn light" onclick="loadQueue()">Kuyruğu yenile ↻</button>`)+`<div class="notice"><strong>Faydalı geri bildirim yaz.</strong> Kabul için bütün ölçütler karşılanmalı. XP yalnızca kabulde ve kullanıcı + görev başına bir kez doğar. Karşılıklı kabul halkaları sunucu tarafından engellenir.</div>${q.length?q.map(reviewCard).join(''):'<div class="empty"><h3>Kuyruk boş.</h3><p>İnceleyebileceğin bekleyen teslim yok.</p></div>'}${isAdmin()?`${section('Değerlendirici yetkileri','Yalnızca yöneticiler görür. Rol değişiklikleri denetim kaydına yazılır.')}<div id="adminUsers">${adminUsers()}</div>`:''}`}
function reviewCard(s){return `<article class="panel" style="margin-bottom:16px"><div class="eyebrow">${esc(s.missionTitle)} · ${esc(s.author)} · +${s.xp} XP</div><h3>${esc(s.title)}</h3>${s.status==='appealed'?`<div class="review-box"><strong>İtiraz:</strong> ${esc(s.appeal.reason)}<br>${s.previousReviews.map(r=>'<strong>Önceki karar ('+({accept:'kabul',revise:'revizyon',reject:'ret'}[r.decision])+'):</strong> '+esc(r.feedback)).join('<br>')}</div>`:''}<div class="read-note">${esc(s.output).replace(/\n/g,'<br>')}<br><small>Etki: ${esc(s.impact)}</small></div><div class="fund-check">${s.acceptance.map((a,i)=>`<label><input type="checkbox" id="chk-${esc(s.id)}-${i}"><span>${esc(a)}</span></label>`).join('')}</div><label class="field" for="fb-${esc(s.id)}">Geri bildirim (en az 40 karakter)</label><textarea id="fb-${esc(s.id)}" minlength="40" maxlength="2000" placeholder="Neyi iyi yaptı? Neyi nasıl geliştirebilir?"></textarea><p class="error" id="err-${esc(s.id)}" role="alert"></p><div class="modal-actions"><button class="btn purple small" onclick="sendReview('${esc(s.id)}','accept',${s.acceptance.length})">Kabul et</button><button class="btn light small" onclick="sendReview('${esc(s.id)}','revise',${s.acceptance.length})">Revizyon iste</button><button class="btn light small" onclick="sendReview('${esc(s.id)}','reject',${s.acceptance.length})">Reddet</button><button class="text-btn" onclick="declareConflict('${esc(s.id)}')">Çıkar çatışması beyan et</button></div></article>`}
async function loadQueue(){try{live.queue=(await api('GET','/api/reviews/queue')).queue;if(isAdmin())live.users=(await api('GET','/api/admin/users')).users}catch(err){toast(err.message)}if(page==='review')$('main').innerHTML=renderReview()}
async function sendReview(id,decision,n){const checks=Array.from({length:n},(_,i)=>!!$(`chk-${id}-${i}`)?.checked);try{const r=await api('POST',`/api/submissions/${encodeURIComponent(id)}/reviews`,{decision,checks,feedback:$('fb-'+id).value});addActivity('Bir teslimi bağımsız olarak değerlendirdin',{accept:'Kabul',revise:'Revizyon',reject:'Ret'}[decision]);save();await refreshLive();await loadQueue();toast(r.xpAwarded?`Kabul edildi. Katılımcıya +${r.xpAwarded} doğrulanmış XP yazıldı.`:'Değerlendirmen kaydedildi.')}catch(err){$('err-'+id).textContent=err.message}}
async function declareConflict(id){const reason=prompt('Çıkar çatışmasını kısaca yaz (ör. aynı ekipteyiz):','Aynı ekip / tanıdık');if(reason===null)return;try{await api('POST',`/api/submissions/${encodeURIComponent(id)}/conflict`,{reason});await loadQueue();toast('Beyanın kaydedildi; teslim başka bir değerlendiriciye kalır.')}catch(err){toast(err.message)}}
function adminUsers(){return live.users.map(u=>`<div class="review-box"><strong>${esc(u.name)}</strong> · ${esc(u.email)} · ${u.xp} XP<br><label><input type="checkbox" ${u.roles.includes('reviewer')?'checked':''} ${u.id===live.user.id?'disabled':''} onchange="setRole('${esc(u.id)}','reviewer',this.checked)"> Değerlendirici</label></div>`).join('')}
async function setRole(id,role,enabled){try{await api('POST',`/api/admin/users/${encodeURIComponent(id)}/roles`,{role,enabled});await loadQueue();toast('Rol güncellendi.')}catch(err){toast(err.message)}}

$('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){searchTerm=e.currentTarget.value.trim();searchPlatform()}});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('globalSearch').focus()}});$('modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});window.addEventListener('hashchange',()=>renderPage(location.hash.slice(1)));renderPage(pageNames[location.hash.slice(1)]?location.hash.slice(1):'home');initLive();
